head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst74200";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jlddst74200.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_fncSearch_onclick
 * @description btn_fncSearch 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fncSearch_onclick = async function(e){
    try {
        await scwin.fncSearch(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst74200.btn_fncSearch_onclick' }); }
};

/**
 * @method
 * @name btn_download_onclick
 * @description btn_download 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_download_onclick = async function(e){
    try {
        await scwin.download(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst74200.btn_download_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fncSearch
 * @description fnc Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fncSearch = async function () {
    const sbmOptions = {
        id: "tx_fncSearch",
        method: "post",
        action: "/listinvstg/newliststkprc.do?method=searchNewListStkprcSub",
        ref: "dma_fncSearchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_download
 * @description download 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_download = async function () {
    const sbmOptions = {
        id: "tx_download",
        method: "post",
        action: "/listinvstg/newliststkprc.do?method=searchNewListStkprcSub",
        ref: "dma_downloadReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fncSearch
 * @description fnc Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fncSearch = async function () {
    const arrVal = $c.util.getComponent('slc_period').getValue().split('|');
    $c.util.getComponent('dma_fncSearchReq').set('strtDd', arrVal[0].replace(/\-/g, ''));
    $c.util.getComponent('dma_fncSearchReq').set('endDd', arrVal[1].replace(/\-/g, ''));
    $c.util.getComponent('dma_fncSearchReq').set('valuTpCd', arrVal[2]);
    $c.util.getComponent('dma_fncSearchReq').set('yyyy', arrVal[3]);
    $c.util.getComponent('dma_fncSearchReq').set('checkYn', "1");
    $c.util.getComponent('dma_fncSearchReq').set('mbrNo', "A");
    if ((($c.util.getComponent('rd_marketType').getValue() == null ? '' : String($c.util.getComponent('rd_marketType').getValue())) === '') === true) {
        $c.util.getComponent('dma_fncSearchReq').set('mktCd', "A");
    } else {
        if (($c.util.getComponent('rd_marketType').getValue() === '1') === true) {
            $c.util.getComponent('dma_fncSearchReq').set('mktCd', "1");
        } else {
            if (($c.util.getComponent('rd_marketType').getValue() === '2') === true) {
                $c.util.getComponent('dma_fncSearchReq').set('mktCd', "2");
            }
        }
    }
    $c.util.getComponent('dma_fncSearchReq').set('method', "searchNewListStkprcSub");
    $c.util.getComponent('dma_fncSearchReq').set('forward', "newListStkprc_sub");
    (document.frm || { elements: [] }).target = "iframe";
    await scwin.tx_fncSearch();
};

/**
 * @method
 * @name download
 * @description download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.download = async function () {
    const arrVal = $c.util.getComponent('slc_period').getValue().split('|');
    $c.util.getComponent('dma_fncSearchReq').set('strtDd', arrVal[0].replace(/\-/g, ''));
    $c.util.getComponent('dma_fncSearchReq').set('endDd', arrVal[1].replace(/\-/g, ''));
    $c.util.getComponent('dma_fncSearchReq').set('valuTpCd', arrVal[2]);
    $c.util.getComponent('dma_fncSearchReq').set('yyyy', arrVal[3]);
    $c.util.getComponent('dma_fncSearchReq').set('checkYn', "1");
    $c.util.getComponent('dma_fncSearchReq').set('mbrNo', "A");
    if ((($c.util.getComponent('rd_marketType').getValue() == null ? '' : String($c.util.getComponent('rd_marketType').getValue())) === '') === true) {
        $c.util.getComponent('dma_fncSearchReq').set('mktCd', "A");
    } else {
        if (($c.util.getComponent('rd_marketType').getValue() === '1') === true) {
            $c.util.getComponent('dma_fncSearchReq').set('mktCd', "1");
        } else {
            if (($c.util.getComponent('rd_marketType').getValue() === '2') === true) {
                $c.util.getComponent('dma_fncSearchReq').set('mktCd', "2");
            }
        }
    }
    $c.util.getComponent('dma_fncSearchReq').set('method', "searchNewListStkprcSub");
    $c.util.getComponent('dma_fncSearchReq').set('forward', "newListStkprc_down");
    (document.frm || { elements: [] }).target = "iframe_1";
    await scwin.tx_download();
};
